def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            color = values[i]
            j = i + 1
            while j < len(values) and values[j] == color:
                j += 1
            result.append((i, j, color))  # half-open interval
            i = j
        return result

    candidates = []

    # Bars on top and bottom edges: markers project vertically.
    top = edge_runs(grid[0])
    bottom = edge_runs(grid[-1])
    for a in top:
        for b in bottom:
            if a[2] == b[2]:
                candidates.append(("horizontal", a, b))

    # Bars on left and right edges: markers project horizontally.
    left = edge_runs([grid[r][0] for r in range(h)])
    right = edge_runs([grid[r][-1] for r in range(h)])
    for a in left:
        for b in right:
            if a[2] == b[2]:
                candidates.append(("vertical", a, b))

    if not candidates:
        return out

    # The paired border bars define the direction and coordinate mapping.
    axis, first, second = max(
        candidates,
        key=lambda item: (item[1][1] - item[1][0]) +
                         (item[2][1] - item[2][0])
    )
    bar_color = first[2]
    markers = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or grid[r][c] == bar_color:
                continue
            pos = c if axis == "horizontal" else r

            if first[0] <= pos < first[1]:
                own_first = True
                offset = pos - first[0]
                mapped = second[0] + offset
            elif second[0] <= pos < second[1]:
                own_first = False
                offset = pos - second[0]
                mapped = first[0] + offset
            else:
                continue

            if mapped >= (second[1] if own_first else first[1]):
                continue

            color = grid[r][c]
            markers.append((r, c))

            if axis == "horizontal":
                # Draw from this marker toward the edge containing its bar.
                if own_first:  # top edge
                    for rr in range(1, r):
                        out[rr][c] = color
                else:  # bottom edge
                    for rr in range(r + 1, h - 1):
                        out[rr][c] = color

                # Its corresponding line spans the whole grid.
                for rr in range(h):
                    if grid[rr][mapped] != bar_color:
                        out[rr][mapped] = color
            else:
                # Draw from this marker toward the edge containing its bar.
                if own_first:  # left edge
                    for cc in range(1, c):
                        out[r][cc] = color
                else:  # right edge
                    for cc in range(c + 1, w - 1):
                        out[r][cc] = color

                # Its corresponding line spans the whole grid.
                for cc in range(w):
                    if grid[mapped][cc] != bar_color:
                        out[mapped][cc] = color

    for r, c in markers:
        out[r][c] = 4

    return out
